# 从排序列表中删除重复的结点
def remove_duplicates(self):
    # 处理空链表的条件
    if not self.head:
        return
    current = self.head 
    # 遍历链表
    while current.next:
        #如果当前结点和下一个结点相等
        #删除下一个结点
        if current.data == current.next.data:
            current.next = current.next.next
        else:
            current = current.next

def reverse_elements(self):
    values = []
    current = self.head
    while current:
        values.append(current.data)
        current = current.next

    current = self.head
    for value in reversed(values):
        current.data = value
        current = current.next

